  @override Widget build(BuildContext context){if(checking)return const Scaffold(body:Center(child:CircularProgressIndicator())); if(businesses.isEmpty && selected==null && signedIn)return Scaffold(appBar:AppBar(title:const Text('Creatarsh Business'),actions:[IconButton(onPressed:_logout,icon:const Icon(Icons.logout_rounded))]),body:Center(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.storefront_outlined,size:56,color:green),const SizedBox(height:16),const Text('No business workspace yet',style:TextStyle(fontSize:23,fontWeight:FontWeight.w900)),const SizedBox(height:8),Text(error??'This account has no active business membership. Create a business profile or claim an existing listing on Creatarsh, then sign in again.',textAlign:TextAlign.center),const SizedBox(height:16),FilledButton(onPressed:_logout,child:const Text('Sign out'))])))); if(businesses.isEmpty && selected==null)return LoginScreen(api:api,onLogin:()async{setState(()=>checking=true);try{await api.me();signedIn=true;await _loadBusinesses();if(businesses.isEmpty)error='No active business membership was found for this account. Create or claim a business profile on Creatarsh first.';}on ApiFailure catch(e){error=e.message;}finally{if(mounted)setState(()=>checking=false);}} ,message:error);
    final pages=<Widget>[_overview(),_profileEditor(),_analyticsPage(),_enquiriesPage(),_storePage()];
