  Widget _storePage(){if(dashboard['storeEnabled']!=true)return _hero('Store','Your business store is not enabled. Product and order tools appear here only when enabled by the platform.');return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[_hero('Products & orders','Store data is isolated to this business.'),Align(alignment:Alignment.centerRight,child:FilledButton.icon(onPressed:()=>_addProduct(),icon:const Icon(Icons.add),label:const Text('Add product'))),if(products.isEmpty)const Card(child:Padding(padding:EdgeInsets.all(16),child:Text('No products found.'))) else ...products.map((p)=>Card(child:ListTile(title:Text('${p['name']??'Product'}'),subtitle:Text('SKU ${p['sku']??'—'} • Stock ${p['stock']??0}'),trailing:Text('₹${p['price']??0}')))),const Card(child:ListTile(title:Text('Orders'),subtitle:Text('Order integration is pending in the current shared API. No unrelated platform orders are shown.')))]);}
  Future<void> _addProduct() async { final name=TextEditingController(),price=TextEditingController(),sku=TextEditingController(),stock=TextEditingController(text:'0'); final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Add product'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Product name')),TextField(controller:price,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Price (₹)')),TextField(controller:sku,decoration:const InputDecoration(labelText:'SKU (optional)')),TextField(controller:stock,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Stock'))])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Save'))])); if(ok==true&&selected!=null){try{await api.createProduct(selected!.id,name:name.text.trim(),price:double.parse(price.text),sku:sku.text.trim(),stock:int.tryParse(stock.text)??0);final p=await api.products(selected!.id);if(mounted)setState(()=>products=p);}catch(e){if(mounted)setState(()=>error=e.toString());}} name.dispose();price.dispose();sku.dispose();stock.dispose();}
  Widget _hero(String title,String sub)=>Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xffe3f8ec),Color(0xffffffff)]),borderRadius:BorderRadius.circular(24),border:Border.all(color:const Color(0xffd8eee1))),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontSize:24,fontWeight:FontWeight.w900)),const SizedBox(height:6),Text(sub,style:const TextStyle(color:Color(0xff52675c)))]));
