}

class LoginScreen extends StatefulWidget {const LoginScreen({super.key,required this.api,required this.onLogin,this.message});final BusinessApi api;final Future<void> Function() onLogin;final String? message;@override State<LoginScreen> createState()=>_LoginScreenState();}
