class _ProfileEditorState extends State<ProfileEditor>{late final name=TextEditingController(text:'${widget.initial['name']??''}');late final description=TextEditingController(text:'${widget.initial['description']??''}');late final category=TextEditingController(text:'${widget.initial['category']??''}');late final phone=TextEditingController(text:'${widget.initial['phone']??''}');late final email=TextEditingController(text:'${widget.initial['email']??''}');late final website=TextEditingController(text:'${widget.initial['websiteUrl']??''}');late final city=TextEditingController(text:'${widget.initial['city']??''}');late final pin=TextEditingController(text:'${widget.initial['pinCode']??''}');bool saving=false;String? message;@override void dispose(){for(final c in [name,description,category,phone,email,website,city,pin]){c.dispose();}super.dispose();}Future<void> save()async{setState(()=>{saving=true,message=null});try{await widget.onSave({'name':name.text.trim(),'description':description.text.trim(),'category':category.text.trim(),'phone':phone.text.trim(),'email':email.text.trim(),'websiteUrl':website.text.trim(),'city':city.text.trim(),'pinCode':pin.text.trim()});setState(()=>message='Profile saved.');}catch(e){setState(()=>message=e.toString());}finally{if(mounted)setState(()=>saving=false);}}@override Widget build(BuildContext context)=>Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Business profile',style:TextStyle(fontSize:23,fontWeight:FontWeight.w900)),const SizedBox(height:8),...[[name,'Business name'],[description,'Description'],[category,'Category'],[phone,'Phone'],[email,'Email'],[website,'Website URL'],[city,'City'],[pin,'PIN code']].map((pair)=>Padding(padding:const EdgeInsets.only(bottom:12),child:TextField(controller:pair[0] as TextEditingController,maxLines:pair[1]=='Description'?3:1,decoration:InputDecoration(labelText:pair[1])))),if(message!=null)Text(message!),FilledButton(onPressed:saving?null:save,child:Text(saving?'Sa